    return "warning"


def log_events(events: list[dict]) -> None:
    """Record a non-displaying event to the journal.

    Warnings are evidence, not emergencies. They are written to the journal
    so they are still auditable, but they never take over the display --
    a fullscreen takeover for a USB mouse is a nuisance, not a warning.
    """
    payload = {
        "severity": most_severe(events),
        "events": events,
        "timestamp": time.strftime("%Y-%m-%d %H:%M:%S"),
    }
    log(f"WARN (no display): {len(events)} event(s)")
    for e in events:
        log(f"        {e['label']} x{e['count']}")
