#!/usr/bin/env python3
"""
BDE PAM Authentication Helper
Captures bioelectric resonance signature and verifies against enrolled profile.
Exit 0 = granted, Exit 1 = denied, Exit 2 = unavailable (no verdict).

Exit 2 is the important one. A missing daemon, an absent socket or a timeout
is NOT a failed authentication -- it is the absence of one. The PAM stack must
be able to tell those apart, because bde-hardlock.pam pairs this with
pam_deny.so, and conflating the two locks you out of login, sudo and ssh.
"""
import json
import os
import pwd
import socket
import sys
import struct

# Failure policy. "open" (default) treats an unavailable verifier as granted so
# a dead daemon can never deny login. "closed" enforces biometrics strictly and
# WILL lock you out if the daemon is down -- only for a machine with a console
# you can physically reach.
FAILMODE = os.environ.get("BDE_FAILMODE", "open").lower()

EXIT_GRANTED = 0
EXIT_DENIED = 1
EXIT_UNAVAILABLE = 2


def socket_path() -> str:
    """Locate the daemon socket for the user being authenticated.

    PAM runs as root, so os.getuid() is 0 and is the wrong answer. Resolve the
    target user's uid instead -- the daemon is a per-user service. A hardcoded
    /run/user/1000 belonged to the old 'sin' account and silently pointed at a
    socket that never existed.
    """
    override = os.environ.get("BDE_SOCK")
    if override:
        return override
    identity = os.environ.get("PAM_USER")
    if identity:
        try:
            return f"/run/user/{pwd.getpwnam(identity).pw_uid}/bde-daemon.sock"
        except KeyError:
            pass
    xdg = os.environ.get("XDG_RUNTIME_DIR")
    if xdg:
        return os.path.join(xdg, "bde-daemon.sock")
    return f"/run/user/{os.getuid()}/bde-daemon.sock"


def _roundtrip(path: str, request: dict, timeout: float) -> dict:
    s = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
    try:
        s.settimeout(timeout)
        s.connect(path)
        s.sendall(json.dumps(request).encode())
        data = b""
        while True:
            chunk = s.recv(4096)
            if not chunk:
                break
            data += chunk
            if b"\n" in data:
                break
        return json.loads(data.decode() or "{}")
    finally:
        s.close()


class Unavailable(Exception):
    """The verifier could not be reached, so no verdict exists."""


def talk(payload: bytes) -> dict:
    try:
        return _roundtrip(
            socket_path(),
            {
                "action": "verify",
                "identity": os.environ.get("PAM_USER", "user"),
                "payload": payload.hex(),
            },
            10.0,
        )
    except (OSError, ValueError) as exc:
        raise Unavailable(str(exc)) from exc


def capture_live() -> bytes:
    try:
        resp = _roundtrip(socket_path(), {"action": "capture"}, 15.0)
    except (OSError, ValueError) as exc:
        raise Unavailable(str(exc)) from exc
    if resp.get("status") == "ok":
        sig = resp.get("signature", {})
        return bytes.fromhex(sig.get("raw_bytes", ""))
    raise Unavailable(resp.get("reason", "capture did not return a signature"))


def verify_against_profile(identity: str, live_bytes: bytes) -> dict:
    profile_path = f"/var/lib/bde-daemon/{identity}.profile"
    if not os.path.exists(profile_path):
        return {"status": "denied", "reason": "no_profile"}
    stored_bytes = open(profile_path, "rb").read()
    if len(stored_bytes) != len(live_bytes):
        return {"status": "denied", "reason": "feature_mismatch"}
    n = len(stored_bytes) // 8
    if n == 0:
        return {"status": "denied", "reason": "empty_profile"}
    stored_arr = list(struct.unpack(f"{n}d", stored_bytes))
    live_arr = list(struct.unpack(f"{n}d", live_bytes))
    mean_s = sum(stored_arr) / n
    mean_l = sum(live_arr) / n
    cov = sum((s - mean_s) * (l - mean_l) for s, l in zip(stored_arr, live_arr)) / n
    std_s = (sum((s - mean_s) ** 2 for s in stored_arr) / n) ** 0.5
    std_l = (sum((l - mean_l) ** 2 for l in live_arr) / n) ** 0.5
    if std_s == 0 or std_l == 0:
        return {"status": "denied", "reason": "zero_variance"}
    corr = cov / (std_s * std_l)
    return {"status": "granted" if corr >= 0.85 else "denied", "correlation": round(corr, 4)}


def main():
    identity = os.environ.get("PAM_USER", "user")
    try:
        live_bytes = capture_live()
    except Unavailable as exc:
        # No verdict, not a denial. Only a strict failmode turns this into a
        # refusal, and it says so on stderr so the cause is findable in the
        # auth log instead of looking like a wrong password.
        print(f"bde-auth: verifier unavailable ({exc}); failmode={FAILMODE}", file=sys.stderr)
        return EXIT_GRANTED if FAILMODE == "open" else EXIT_DENIED

    if not live_bytes:
        return EXIT_DENIED

    result = verify_against_profile(identity, live_bytes)
    if result.get("status") == "granted":
        return EXIT_GRANTED
    print(f"bde-auth: denied ({result.get('reason')})", file=sys.stderr)
    return EXIT_DENIED


if __name__ == "__main__":
    sys.exit(main())

