import json, re, sys

def strip_comments(src):
    """Remove // and /* */ comments, skipping string literals so URLs survive."""
    out, i, n = [], 0, len(src)
    while i < n:
        c = src[i]
        if c == '"':
            out.append(c); i += 1
            while i < n:                      # copy string verbatim, honouring escapes
                out.append(src[i])
                if src[i] == '\\':
                    i += 1
                    if i < n: out.append(src[i])
                elif src[i] == '"':
                    i += 1
                    break
                i += 1
            continue
        if src.startswith('//', i):
            while i < n and src[i] != '\n': i += 1
            continue
        if src.startswith('/*', i):
            end = src.find('*/', i + 2)
            i = n if end == -1 else end + 2
            continue
        out.append(c); i += 1
    return ''.join(out)

p = sys.argv[1]
try:
    cfg = json.loads(strip_comments(open(p).read()))
except Exception:
    sys.exit(1)
cfg['theme'] = 'voidlit'
open(p, 'w').write(json.dumps(cfg, indent=2) + '\n')

