input.command:
cd ~/Projects/zen-hardening
t=$(mktemp); cp shield-kitty-fail2ban.local "$t"
set_rec() { local want="$1" file="$2"
  awk -v want="$want" '
    /^\[recidive\]/           { inrec = 1 }
    /^\[/ && !/^\[recidive\]/ { inrec = 0 }
    inrec && /^[[:space:]]*enabled[[:space:]]*=/ { print "enabled  = " want; next }
    { print }
  ' "$file" > "$file.new" && mv "$file.new" "$file"
}
show(){ awk '/^\[/{s=$0} /^enabled/{printf "    %-12s %s\n",s,$0}' "$1"; }
echo "  before:";      show "$t"
set_rec false "$t"; echo "  -> false:";  show "$t"
set_rec true  "$t"; echo "  -> true:";   show "$t"
echo
echo "  line count unchanged?  before=$(wc -l < shield-kitty-fail2ban.local) after=$(wc -l < "$t")"
echo "  diff vs original (only recidive should differ):"
diff <(cat shield-kitty-fail2ban.local) "$t" | sed 's/^/    /' || true
rm -f "$t"

